#!/usr/bin/env python3
"""Build deterministic, offline observation explorer from the exact reader."""
import json
from pathlib import Path
from vol8_reader import PANEL, OPTIMAL_PANEL, NAMES, matrix, invert
HERE = Path(__file__).resolve().parent

def main():
    panels = []
    for degrees in (PANEL, OPTIMAL_PANEL):
        m = matrix(degrees); inv, det = invert(m)
        panels.append({'degrees': degrees, 'matrix': [[int(x) for x in row] for row in m],
                       'inverse': [[float(x) for x in row] for row in inv],
                       'exactInverse': [[str(x) for x in row] for row in inv],
                       'det': str(det), 'gain': str(max(sum(map(abs, row)) for row in inv))})
    data = json.dumps({'names': NAMES, 'panels': panels}, separators=(',', ':'))
    html = '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Singularity · Seven hidden coordinates</title>
<style>
:root{color-scheme:dark;font-family:system-ui,sans-serif;color:#edf1f5;background:#101820}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 80% 0,#193d45,transparent 55%)}main{max-width:1180px;margin:auto;padding:52px 28px}header{border-bottom:1px solid #40616a;padding-bottom:30px}.eyebrow{letter-spacing:.22em;color:#8cd5c9;font-size:12px}h1{font:clamp(38px,5vw,66px)/1.04 Georgia,serif;font-weight:normal;max-width:850px;margin:20px 0}p{line-height:1.65;color:#b6c9ce;max-width:830px}.formula{font:22px Georgia,serif;color:#f3cf92;line-height:1.8}.rank{display:flex;gap:30px;align-items:center;margin:24px 0}.rank strong{font:42px Georgia,serif}.rank span{font-size:13px;color:#a6bfc4}section{margin:32px 0}h2{font:28px Georgia,serif}button,select,input{font:inherit}select,button{background:#1e343c;color:#eef8f8;border:1px solid #54777d;border-radius:5px;padding:9px}button{cursor:pointer}label{color:#bdd1d5}table{border-collapse:collapse;width:100%;font-size:13px;font-variant-numeric:tabular-nums}td,th{padding:10px 7px;text-align:right;border:1px solid #35505a}th{color:#bcd3d8;font-weight:500}td{font-family:ui-monospace,monospace}.scroll{overflow:auto}#controls{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:16px}#controls label{display:flex;flex-direction:column;gap:8px}input[type=range]{width:100%;accent-color:#8edbcb}output{font:21px Georgia,serif;color:#f3cf92}.pair{display:grid;grid-template-columns:1fr 1fr;gap:28px}.note{font-size:13px;border-left:2px solid #d4aa68;padding-left:15px}.toolbar{display:flex;align-items:center;gap:15px;flex-wrap:wrap}footer{border-top:1px solid #40616a;padding-top:22px;color:#a1bbc1;font-size:12px}a{color:#8cdbce}@media(max-width:700px){.pair{grid-template-columns:1fr}main{padding:28px 15px}td,th{padding:8px 4px}.rank{gap:18px}}</style>
<main><header><div class="eyebrow">SINGULARITY / EXACT HEIGHT-SERIES OBSERVATION</div><h1>Seven coordinates.<br>One new layer of sight.</h1><p>When finite simple cubic graphs agree through volume seven, their eighth-order height difference reveals five corrected core sums and two six-vertex motifs that earlier observations could not distinguish.</p><div class="rank"><div><strong>17</strong><br><span>through volume 7</span></div><strong>→</strong><div><strong>24</strong><br><span>through volume 8</span></div><div><strong>7</strong><br><span>new independent coordinates</span></div></div><div class="formula">ΔN<sub>T</sub> = −c₂₈ − 6c₃₀ &nbsp; · &nbsp; ΔN<sub>D</sub> = c₂₈ + 5c₃₀</div></header>
<section><div class="toolbar"><h2>Choose the coefficient lens</h2><select id="panel" aria-label="Coefficient panel"><option value="0">Tail-readable panel</option><option value="1">Minimum worst-case error gain</option></select></div><p id="stats"></p><div class="scroll" id="matrix"></div><p class="note">Rows are measured coefficient degrees; columns are invariant differences. Teal is positive, amber is negative. Color intensity uses log magnitude; numbers remain exact.</p></section>
<section><h2>Compose a difference</h2><p>Move the seven coordinates to see the coefficient measurements and inverse reconstruction. This explores the observation map; these freely chosen vectors do not assert the existence of a particular connected graph pair.</p><div id="controls"></div><div class="pair"><div><h2>Measurements</h2><div id="measure"></div></div><div><h2>Recovered coordinates</h2><div id="recover"></div></div></div></section>
<section><h2>Measurement sensitivity</h2><div class="toolbar"><label>Absolute error per difference coefficient: <input id="epsilon" type="number" min="0" max="1000" step="0.001" value="0.01"></label></div><p id="sensitivity"></p><p class="note">Conditional numerical propagation: assumes exact agreement through volume seven and the seven-coordinate model. These browser estimates exclude rounding error and are not integer certificates. Use the Python reader for exact rational validation of complete input polynomials.</p></section>
<section><h2>The exact inverse</h2><div class="scroll" id="inverse"></div></section><footer>Δ = B − A. Q₀ = S₈,₈ + N<sub>B</sub>; Q₁ = S₈,₉ − 2N<sub>P</sub> + N<sub>D</sub>. Source: vol8_reader.py and the unchanged volume-eight proof. Every number in the matrix and exact inverse is generated from rational polynomial factors. Exhaustive search: 11,440 panels, 10,710 invertible; objective ||M⁻¹||∞ under equal unscaled coefficient-error bounds.</footer></main>
<script>const DATA=__DATA__;const $=id=>document.getElementById(id);let values=[1,0,0,0,0,0,0];
function table(rows,cols,body,heat=false){let h='<table><thead><tr><th></th>'+cols.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>';body.forEach((row,i)=>{h+='<tr><th>'+rows[i]+'</th>';row.forEach(x=>{let n=Number(x),alpha=n?Math.min(.8,.12+Math.log1p(Math.abs(n))/12):0;h+='<td'+(heat?' style="background:rgba('+(n>0?'51,167,155':'203,143,66')+','+alpha+')"':'')+'>'+x+'</td>'});h+='</tr>'});return h+'</tbody></table>'}
function draw(){let p=DATA.panels[Number($('panel').value)];$('stats').textContent='Degrees '+p.degrees.join(', ')+' · determinant '+p.det+' · worst-case absolute error gain '+p.gain;$('matrix').innerHTML=table(p.degrees.map(e=>'q^'+e),DATA.names,p.matrix,true);$('inverse').innerHTML=table(DATA.names,p.degrees.map(e=>'c'+e),p.exactInverse);let y=p.matrix.map(row=>row.reduce((s,x,j)=>s+x*values[j],0));let recovered=p.inverse.map(row=>row.reduce((s,x,j)=>s+x*y[j],0));$('measure').innerHTML=table(p.degrees.map(e=>'c'+e),['value'],y.map(x=>[x]));$('recover').innerHTML=table(DATA.names,['estimate'],recovered.map(x=>[Number(x.toFixed(8))]));let epsilon=Number($('epsilon').value);$('sensitivity').textContent=Number.isFinite(epsilon)&&epsilon>=0?'Per-coordinate measurement-error estimates: '+DATA.names.map((n,i)=>n+' ± '+(epsilon*p.inverse[i].reduce((s,x)=>s+Math.abs(x),0)).toPrecision(4)).join(' · '):'Enter a finite nonnegative error.';}
DATA.names.forEach((n,i)=>{let label=document.createElement('label');label.textContent=n;let input=document.createElement('input');input.type='range';input.min=-5;input.max=5;input.step=1;input.value=values[i];let output=document.createElement('output');output.textContent=values[i];input.oninput=()=>{values[i]=Number(input.value);output.textContent=input.value;draw()};label.append(input,output);$('controls').append(label)});$('panel').onchange=draw;$('epsilon').oninput=draw;draw();</script></html>'''
    (HERE/'vol8_reader.html').write_text(html.replace('__DATA__', data)+'\n')

if __name__ == '__main__':
    main()
